<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response,Validator};
use App\Repositories\{AcademicRepository,SettingsRepository,StudentRepository,UserRepository};
use App\Services\SettingsService;
use App\Support\{Flash,UploadPolicy};

final class SettingsController extends AdminPageController
{
    private function repo(): SettingsRepository{return new SettingsRepository($this->app->database());}
    private function denied(): ?Response{return can('settings.view')?null:Response::html('Forbidden',403);}
    private function fail(string $path,array $errors,array $old=[]): Response{$this->app->session()->flash('_errors',$errors);$this->app->session()->flash('_old',$old);Flash::add('error',reset($errors)[0]??'Please correct the form.');return Response::redirect(url($path));}
    private function instituteId(): int{return (int)$this->repo()->institute()['id'];}
    public function account(Request $r): Response {if($x=$this->denied())return $x;return $this->renderPage('account-settings',['institute'=>$this->repo()->institute()]);}
    public function updateAccount(Request $r): Response {if($x=$this->denied())return $x;$data=['account_email'=>trim((string)$r->input('account_email')),'account_password'=>(string)$r->input('account_password'),'timezone'=>(string)$r->input('timezone'),'currency'=>(string)$r->input('currency'),'currency_symbol'=>trim((string)$r->input('currency_symbol'))];$v=new Validator();if(!$v->validate($data,['account_email'=>'required|email|max:190','timezone'=>'required|in:Asia/Karachi,Asia/Dubai,Asia/Riyadh,Europe/London,America/New_York,UTC','currency'=>'required|in:PKR,USD,SAR,AED,GBP,EUR','currency_symbol'=>'required|max:8']))return $this->fail('/admin/settings/account',$v->errors(),$data);if($data['account_password']!==''&&strlen($data['account_password'])<12)return $this->fail('/admin/settings/account',['account_password'=>['Password must be at least 12 characters.']],$data);$u=user();try{(new UserRepository($this->app->database()))->updateAccount((int)$u['id'],$data['account_email'],$data['account_password']?:null);$this->repo()->updatePreferences($this->instituteId(),['timezone'=>$data['timezone'],'currency'=>$data['currency'],'currency_symbol'=>$data['currency_symbol']]);$u['email']=strtolower($data['account_email']);$this->app->session()->set('auth_user',$u);}catch(\PDOException){return $this->fail('/admin/settings/account',['account_email'=>['That email address is already in use.']],$data);}Flash::add('success','Account settings updated.');return Response::redirect(url('/admin/settings/account'));}
    public function instituteProfile(Request $r): Response {if($x=$this->denied())return $x;return $this->renderPage('institute-profile',['institute'=>$this->repo()->institute()]);}
    public function updateInstituteProfile(Request $r): Response {if($x=$this->denied())return $x;$data=['institute_name'=>trim((string)$r->input('institute_name')),'target_line'=>trim((string)$r->input('target_line')),'phone_number'=>trim((string)$r->input('phone_number')),'website'=>trim((string)$r->input('website')),'address'=>trim((string)$r->input('address')),'country'=>(string)$r->input('country')];$v=new Validator();if(!$v->validate($data,['institute_name'=>'required|max:160','target_line'=>'required|max:255','phone_number'=>'required|max:50','website'=>'url|max:255','address'=>'required|max:2000','country'=>'required|max:100']))return $this->fail('/admin/settings/institute-profile',$v->errors(),$data);$logo=$this->storeImage($r->file('institute_logo'),'institutes',false);if($logo===false)return $this->fail('/admin/settings/institute-profile',['institute_logo'=>['Logo must be a JPG or PNG no larger than 500KB.']],$data);$this->repo()->updateInstitute($this->instituteId(),['name'=>$data['institute_name'],'target_line'=>$data['target_line'],'phone'=>$data['phone_number'],'website'=>$data['website']?:null,'address'=>$data['address'],'country'=>$data['country'],'logo_path'=>$logo]);Flash::add('success','Institute profile updated.');return Response::redirect(url('/admin/settings/institute-profile'));}
    private function storeImage(?array $file,string $folder,bool $required): string|false|null {if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return $required?false:null;$policy=new UploadPolicy(['image/jpeg','image/png'],['jpg','jpeg','png'],512000);if(!$policy->validate($file))return false;$name=$policy->safeFilename(pathinfo((string)$file['name'],PATHINFO_EXTENSION));$dir=BASE_PATH.'/public/uploads/'.$folder;if(!is_dir($dir))mkdir($dir,0775,true);if(!move_uploaded_file((string)$file['tmp_name'],$dir.'/'.$name))throw new \RuntimeException('Unable to store image.');return 'uploads/'.$folder.'/'.$name;}
    private function feeScope(Request $r): array{$mode=(string)$r->input('fee_month_mode','all');$target=(string)$r->input('fee_scope','all');$months=array_flip(['January','February','March','April','May','June','July','August','September','October','November','December']);return ['month_scope'=>$mode,'month_number'=>$mode==='specific'?(($months[(string)$r->input('specific_month')]??-1)+1):null,'target_scope'=>$target,'target_reference'=>$target==='class'?(string)$r->input('scope_class'):($target==='student'?(string)$r->input('scope_student'):null)];}
    private function validFeeScope(array $scope,int $instituteId): bool{if($scope['target_scope']==='all')return true;if($scope['target_scope']==='class')foreach((new AcademicRepository($this->app->database()))->classes($instituteId) as $class)if($class['name']===$scope['target_reference'])return true;return $scope['target_scope']==='student'&&(new StudentRepository($this->app->database()))->byRegistration((string)$scope['target_reference'],$instituteId)!==null;}
    private function feeScopeUrl(array $scope): string{$months=['January','February','March','April','May','June','July','August','September','October','November','December'];$query=['fee_month_mode'=>$scope['month_scope'],'fee_scope'=>$scope['target_scope']];if($scope['month_scope']==='specific')$query['specific_month']=$months[(int)$scope['month_number']-1]??'';if($scope['target_scope']==='class')$query['scope_class']=$scope['target_reference'];if($scope['target_scope']==='student')$query['scope_student']=$scope['target_reference'];return url('/admin/settings/fee-particulars').'?'.http_build_query($query);}
    public function feeParticulars(Request $r): Response {if($x=$this->denied())return $x;$scope=$this->feeScope($r);$id=$this->instituteId();return $this->renderPage('fee-particulars',['feeItems'=>SettingsService::FEE_ITEMS,'savedFees'=>$this->repo()->feeParticulars($id,$scope),'scope'=>$scope,'classes'=>(new AcademicRepository($this->app->database()))->classes($id),'students'=>(new StudentRepository($this->app->database()))->paginate($id,'',null,100)]);}
    public function saveFeeParticulars(Request $r): Response {if($x=$this->denied())return $x;$scope=$this->feeScope($r);$instituteId=$this->instituteId();if(!in_array($scope['month_scope'],['all','specific'],true)||!in_array($scope['target_scope'],['all','class','student'],true)||($scope['month_scope']==='specific'&&(!$scope['month_number']||$scope['month_number']>12))||($scope['target_scope']!=='all'&&trim((string)$scope['target_reference'])==='')||!$this->validFeeScope($scope,$instituteId))return $this->fail('/admin/settings/fee-particulars',['scope'=>['Select a valid month and target scope.']],$r->all());$amounts=[];foreach(SettingsService::FEE_ITEMS as $key=>$label){$value=$r->input('fee_'.$key,0);if(!is_numeric($value)||(float)$value<0)return $this->fail('/admin/settings/fee-particulars',[$key=>['Fee amounts must be zero or greater.']],$r->all());$amounts[$key]=$value;}(new SettingsService($this->repo()))->saveFees($instituteId,$scope,$amounts);Flash::add('success','Fee particulars saved.');return Response::redirect($this->feeScopeUrl($scope));}
    public function feeInvoiceAccounts(Request $r): Response {if($x=$this->denied())return $x;return $this->renderPage('fee-invoice-accounts',['banks'=>$this->repo()->banks($this->instituteId())]);}
    public function addFeeInvoiceAccount(Request $r): Response {if($x=$this->denied())return $x;$data=['bank_name'=>trim((string)$r->input('bank_name')),'account_number'=>trim((string)$r->input('account_number')),'bank_address'=>trim((string)$r->input('bank_address')),'instructions'=>trim((string)$r->input('instructions'))];$v=new Validator();if(!$v->validate($data,['bank_name'=>'required|max:120','account_number'=>'required|max:100','bank_address'=>'required|max:2000','instructions'=>'max:2000']))return $this->fail('/admin/settings/fee-invoice-accounts',$v->errors(),$data);$logo=$this->storeImage($r->file('bank_logo'),'banks',true);if($logo===false)return $this->fail('/admin/settings/fee-invoice-accounts',['bank_logo'=>['Bank logo must be a JPG or PNG no larger than 500KB.']],$data);$this->repo()->addBank($this->instituteId(),$data+['logo_path'=>$logo]);Flash::add('success','Bank account added.');return Response::redirect(url('/admin/settings/fee-invoice-accounts'));}
    public function deleteFeeInvoiceAccount(Request $r): Response {if($x=$this->denied())return $x;$path=$this->repo()->deleteBank((int)$r->route('id'),$this->instituteId());if(!$path)return Response::html('Not found',404);$absolute=BASE_PATH.'/public/'.ltrim($path,'/');if(is_file($absolute))unlink($absolute);Flash::add('success','Bank account deleted.');return Response::redirect(url('/admin/settings/fee-invoice-accounts'));}
    public function rulesRegulations(Request $r): Response {if($x=$this->denied())return $x;return $this->renderPage('rules-regulations',['rules'=>$this->repo()->rules($this->instituteId())]);}
    public function saveRules(Request $r): Response {if($x=$this->denied())return $x;$service=new SettingsService($this->repo());$student=$service->sanitizeHtml((string)$r->input('student_rules'));$employee=$service->sanitizeHtml((string)$r->input('employee_rules'));if(trim(strip_tags($student))===''||trim(strip_tags($employee))==='')return $this->fail('/admin/settings/rules-regulations',['rules'=>['Student and employee rules are required.']],[]);$this->repo()->saveRules($this->instituteId(),['student'=>$student,'employee'=>$employee]);Flash::add('success','Rules and regulations saved.');return Response::redirect(url('/admin/settings/rules-regulations'));}
    public function marksGrading(Request $r): Response {if($x=$this->denied())return $x;return $this->renderPage('marks-grading',['grades'=>$this->repo()->grades($this->instituteId())]);}
    public function saveMarksGrading(Request $r): Response {if($x=$this->denied())return $x;$service=new SettingsService($this->repo());[$grades,$errors]=$service->validateGrades((array)$r->input('grade',[]),(array)$r->input('from',[]),(array)$r->input('upto',[]),(array)$r->input('status',[]));if($errors)return $this->fail('/admin/settings/marks-grading',['grades'=>$errors],$r->all());$pdo=$this->repo()->pdo();$pdo->beginTransaction();try{$this->repo()->replaceGrades($this->instituteId(),$grades);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}Flash::add('success','Grading scale saved.');return Response::redirect(url('/admin/settings/marks-grading'));}
    public function feeStructure(Request$r):Response{if($x=$this->denied())return$x;return$this->renderPage('fee-structure',['classes'=>(new AcademicRepository($this->app->database()))->classes($this->instituteId())]);}
    public function saveFeeStructure(Request$r):Response{if($x=$this->denied())return$x;$fees=(array)$r->input('fee',[]);$classes=(new AcademicRepository($this->app->database()))->classes($this->instituteId());$ids=array_map(fn($c)=>(int)$c['id'],$classes);$valid=[];foreach($fees as$id=>$amount){if(!in_array((int)$id,$ids,true)||!is_numeric($amount)||(float)$amount<0)return Response::html('Invalid class fee',422);$valid[(int)$id]=(float)$amount;}$this->repo()->updateClassFees($this->instituteId(),$valid);Flash::add('success','Fee structure updated.');return Response::redirect(url('/admin/settings/fee-structure'));}
    public function discountTypes(Request$r):Response{if($x=$this->denied())return$x;return$this->renderPage('discount-types',['discounts'=>$this->repo()->discounts($this->instituteId())]);}
    public function saveDiscountType(Request$r):Response{if($x=$this->denied())return$x;$name=trim((string)$r->input('name'));$mode=(string)$r->input('discount_mode');$value=$r->input('discount_value');if($name===''||strlen($name)>120||!in_array($mode,['percentage','fixed'],true)||!is_numeric($value)||(float)$value<0||($mode==='percentage'&&(float)$value>100))return Response::html('Invalid discount type',422);$this->repo()->addDiscount($this->instituteId(),$name,$mode,(float)$value);Flash::add('success','Discount type saved.');return Response::redirect(url('/admin/settings/discount-types'));}
    public function discountTypeStatus(Request$r):Response{if($x=$this->denied())return$x;$status=(string)$r->input('status');if(!in_array($status,['active','inactive'],true))return Response::html('Invalid status',422);if(!$this->repo()->setDiscountStatus((int)$r->route('id'),$this->instituteId(),$status))return Response::html('Discount type not found',404);return Response::redirect(url('/admin/settings/discount-types'));}
    public function themeLanguage(Request$r):Response{if($x=$this->denied())return$x;return$this->renderPage('theme-language',['institute'=>$this->repo()->institute()]);}
    public function saveThemeLanguage(Request$r):Response{if($x=$this->denied())return$x;$theme=(string)$r->input('theme');$language=(string)$r->input('language');if(!in_array($theme,['maroon','system'],true)||!in_array($language,['en','ur'],true))return Response::html('Invalid appearance settings',422);$this->repo()->updateThemeLanguage($this->instituteId(),$theme,$language);Flash::add('success','Theme and language preferences saved.');return Response::redirect(url('/admin/settings/theme-language'));}
}
